<?php use VO\Support\Template; ob_start(); ?><h1>Notificaciones</h1><p class="muted">Registro de envíos a clientes (solo lectura). Los envíos pendientes se procesan al abrir esta página.</p><form method="get" action="/admin/notificaciones" class="card"><label>Estado <select name="state"><option value="">Todos</option><?php foreach($states as $k=>$v):?><option value="<?= $k ?>"<?= $state===$k?' selected':'' ?>><?= $v ?></option><?php endforeach;?></select></label><label>Canal <select name="channel"><option value="">Todos</option><?php foreach($channels as $k=>$v):?><option value="<?= $k ?>"<?= $channel===$k?' selected':'' ?>><?= $v ?></option><?php endforeach;?></select></label><button class="btn">Filtrar</button></form><section class="card"><?php foreach($rows as $r):?><p><strong><?= Template::e($events[$r['event']] ?? $r['event']) ?></strong> · <?= Template::e($channels[$r['channel']] ?? $r['channel']) ?> · <?= Template::e($r['recipient']) ?><?= $r['subject']!==null&&$r['subject']!==''?' · '.Template::e((string)$r['subject']):'' ?> · <span class="state-<?= Template::e((string)$r['state']) ?>"><?= Template::e($states[(string)$r['state']] ?? (string)$r['state']) ?></span> · Intentos: <?= (int)$r['attempts'] ?> · <?= Template::e((string)$r['created_at']) ?><?php $err=(string)($r['last_error']??'');if($err!==''):?><br><span class="muted">Error: <?= Template::e(mb_substr($err,0,120)) ?><?= mb_strlen($err)>120?'…':'' ?></span><?php endif;?></p><?php endforeach;if(!$rows):?><p>No hay notificaciones para mostrar.</p><?php endif;?></section><?php if($pages>1):?><p><?php $qs=static fn(int $p): string => '/admin/notificaciones?'.http_build_query(array_filter(['state'=>$state,'channel'=>$channel,'page'=>$p],static fn(mixed $v): bool => $v!==''));if($page>1):?><a href="<?= Template::e($qs($page-1)) ?>">Anterior</a> <?php endif;?>Página <?= $page ?> de <?= $pages ?><?php if($page<$pages):?> <a href="<?= Template::e($qs($page+1)) ?>">Siguiente</a><?php endif;?></p><?php endif;?><?php $content=ob_get_clean();$title='Notificaciones';require __DIR__.'/layout.php';?>
